package com.campusmart.controller;
import com.campusmart.entity.*; import com.campusmart.repository.*; import com.campusmart.service.UserService; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/cart") public class CartController {private final CartItemRepository r;private final ProductRepository products;private final UserService users;public CartController(CartItemRepository r,ProductRepository p,UserService u){this.r=r;products=p;users=u;}@GetMapping public List<CartItem> get(Authentication a){return r.findByUserId(Long.valueOf(a.getName()));}@PostMapping public CartItem add(@RequestBody Map<String,Object> b,Authentication a){Long uid=Long.valueOf(a.getName()),pid=Long.valueOf(String.valueOf(b.get("productId")));int q=Integer.parseInt(String.valueOf(b.getOrDefault("quantity",1)));if(q<1)throw new IllegalArgumentException("Invalid quantity");Product p=products.findById(pid).orElseThrow(()->new IllegalArgumentException("Product not found"));if(!p.isAvailable())throw new IllegalArgumentException("Product unavailable");CartItem c=r.findByUserIdAndProductId(uid,pid).orElseGet(CartItem::new);c.setUser(users.get(uid));c.setProduct(p);c.setQuantity(c.getId()==null?q:c.getQuantity()+q);return r.save(c);}@PutMapping("/{id}") public CartItem update(@PathVariable Long id,@RequestBody Map<String,Integer> b,Authentication a){CartItem c=r.findById(id).orElseThrow(()->new IllegalArgumentException("Cart item not found"));if(!c.getUser().getId().equals(Long.valueOf(a.getName())))throw new IllegalArgumentException("Forbidden");c.setQuantity(Math.max(1,b.getOrDefault("quantity",1)));return r.save(c);}@DeleteMapping("/{id}") public void delete(@PathVariable Long id,Authentication a){CartItem c=r.findById(id).orElseThrow(()->new IllegalArgumentException("Cart item not found"));if(!c.getUser().getId().equals(Long.valueOf(a.getName())))throw new IllegalArgumentException("Forbidden");r.delete(c);}}
